#!/usr/bin/env python3
"""Autosufficient full snapshots. Python 3.12, standard library, Linux/POSIX."""

import argparse
import contextlib
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import stat
import sys
import tempfile


ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,63}\Z", re.ASCII)
HASH_RE = re.compile(r"[0-9a-f]{64}\Z", re.ASCII)
CHUNK = 1024 * 1024
DIRECTORY = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
REGULAR = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK


class BackupError(Exception):
    pass


def reject(message):
    raise BackupError(message)


def valid_id(value):
    if not ID_RE.fullmatch(value):
        reject("invalid snapshot ID")
    return value


def checked_path(value):
    """Inspect even components preceding '..', without resolving symlinks."""
    raw = os.fspath(value)
    if not raw or "\0" in raw:
        reject("invalid directory path")
    absolute = raw if os.path.isabs(raw) else os.path.join(os.getcwd(), raw)
    current = Path("/")
    missing = False
    for part in absolute.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            if missing:
                reject("nonexistent component before '..'")
            current = current.parent
            continue
        current /= part
        try:
            info = current.lstat()
        except FileNotFoundError:
            missing = True
            continue
        if stat.S_ISLNK(info.st_mode):
            reject("symlink in directory path: " + str(current))
        if not stat.S_ISDIR(info.st_mode):
            reject("non-directory in directory path: " + str(current))
    return current


def overlaps(left, right):
    return left == right or left in right.parents or right in left.parents


def regular_fd(name, parent_fd):
    fd = os.open(name, REGULAR, dir_fd=parent_fd)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        os.close(fd)
        reject("not a regular file: " + name)
    return fd


def scan_tree(root, copy_to=None, hash_files=True):
    """Traverse with directory descriptors; never follow a directory symlink."""
    records = []

    def visit(fd, prefix, target):
        with os.scandir(fd) as children:
            names = sorted(entry.name for entry in children)
        for name in names:
            relative = prefix + name
            info = os.stat(name, dir_fd=fd, follow_symlinks=False)
            if stat.S_ISDIR(info.st_mode):
                records.append({"path": relative, "type": "dir"})
                child_target = target / name if target is not None else None
                if child_target is not None:
                    child_target.mkdir(mode=0o700)
                child_fd = os.open(name, DIRECTORY, dir_fd=fd)
                try:
                    visit(child_fd, relative + "/", child_target)
                finally:
                    os.close(child_fd)
            elif stat.S_ISREG(info.st_mode):
                record = {"path": relative, "type": "file"}
                if hash_files or target is not None:
                    digest = hashlib.sha256()
                    size = 0
                    with os.fdopen(regular_fd(name, fd), "rb") as incoming:
                        with contextlib.ExitStack() as stack:
                            outgoing = None
                            if target is not None:
                                outgoing = stack.enter_context((target / name).open("xb"))
                            while block := incoming.read(CHUNK):
                                digest.update(block)
                                size += len(block)
                                if outgoing is not None:
                                    outgoing.write(block)
                            if outgoing is not None:
                                outgoing.flush()
                                os.fsync(outgoing.fileno())
                    record.update(size=size, sha256=digest.hexdigest())
                records.append(record)
            else:
                reject("symlink or special file: " + relative)

    fd = os.open(root, DIRECTORY)
    try:
        visit(fd, "", copy_to)
    finally:
        os.close(fd)
    return sorted(records, key=lambda entry: entry["path"])


def sync_directory(path):
    fd = os.open(path, DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def sync_tree_directories(root):
    for entry in reversed(scan_tree(root, hash_files=False)):
        if entry["type"] == "dir":
            sync_directory(root / entry["path"])
    sync_directory(root)


@contextlib.contextmanager
def repository(path, create=False):
    if not path.exists():
        if not create:
            reject("repository does not exist")
        path.mkdir(mode=0o700, parents=True)
    fd = os.open(path, DIRECTORY)
    try:
        # A directory lock needs no persistent file and is released after SIGKILL.
        fcntl.flock(fd, fcntl.LOCK_EX)
        scan_tree(path, hash_files=False)
        with os.scandir(fd) as entries:
            for entry in entries:
                if not entry.is_dir(follow_symlinks=False):
                    reject("unexpected file in repository root")
                if not (ID_RE.fullmatch(entry.name) or entry.name.startswith(".stage-")):
                    reject("unexpected directory in repository root")
        yield
    finally:
        os.close(fd)


def read_regular(path):
    parent = os.open(path.parent, DIRECTORY)
    try:
        with os.fdopen(regular_fd(path.name, parent), "rb") as stream:
            return stream.read()
    finally:
        os.close(parent)


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            reject("duplicate JSON key")
        result[key] = value
    return result


def validate_manifest(manifest, snapshot_id):
    if not isinstance(manifest, dict) or set(manifest) != {"format", "id", "entries"}:
        reject("invalid manifest")
    if type(manifest["format"]) is not int or manifest["format"] != 1:
        reject("unsupported manifest format")
    if manifest["id"] != snapshot_id or not isinstance(manifest["entries"], list):
        reject("invalid manifest ID or entries")
    known = {}
    for entry in manifest["entries"]:
        if not isinstance(entry, dict):
            reject("invalid manifest entry")
        path = entry.get("path")
        if not isinstance(path, str) or "\0" in path:
            reject("invalid manifest path")
        parts = path.split("/")
        if any(part in ("", ".", "..") for part in parts) or path in known:
            reject("unsafe or duplicate manifest path")
        if len(parts) > 1 and known.get("/".join(parts[:-1])) != "dir":
            reject("missing parent directory in manifest")
        kind = entry.get("type")
        if kind == "dir":
            if set(entry) != {"path", "type"}:
                reject("invalid directory entry")
        elif kind == "file":
            if set(entry) != {"path", "type", "size", "sha256"}:
                reject("invalid file entry")
            if type(entry["size"]) is not int or entry["size"] < 0:
                reject("invalid file size")
            if not isinstance(entry["sha256"], str) or not HASH_RE.fullmatch(entry["sha256"]):
                reject("invalid file hash")
        else:
            reject("invalid entry type")
        known[path] = kind
    if manifest["entries"] != sorted(manifest["entries"], key=lambda entry: entry["path"]):
        reject("manifest entries must be ordered")
    return manifest["entries"]


def verify_snapshot(snapshot, snapshot_id):
    if not snapshot.is_dir() or snapshot.is_symlink():
        reject("snapshot does not exist or is not a directory")
    if set(os.listdir(snapshot)) != {"tree", "manifest.json", "manifest.sha256"}:
        reject("incomplete or unexpected snapshot structure")
    raw = read_regular(snapshot / "manifest.json")
    checksum = read_regular(snapshot / "manifest.sha256")
    if checksum != (hashlib.sha256(raw).hexdigest() + "\n").encode("ascii"):
        reject("manifest checksum mismatch")
    manifest = json.loads(raw, object_pairs_hook=unique_object)
    expected = validate_manifest(manifest, snapshot_id)
    actual = scan_tree(snapshot / "tree")
    if actual != expected:
        reject("snapshot data or directory structure mismatch")
    return expected


def write_synced(path, data):
    with path.open("xb") as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())


def create(source, repo, snapshot_id):
    if overlaps(source, repo):
        reject("source and repository overlap")
    with repository(repo, create=True):
        snapshot = repo / snapshot_id
        if snapshot.exists():
            reject("snapshot ID already exists")
        stage = Path(tempfile.mkdtemp(prefix=".stage-", dir=repo))
        try:
            tree = stage / "tree"
            tree.mkdir(mode=0o700)
            entries = scan_tree(source, copy_to=tree)
            raw = json.dumps({"format": 1, "id": snapshot_id, "entries": entries},
                             ensure_ascii=True, sort_keys=True, separators=(",", ":")).encode("utf-8")
            write_synced(stage / "manifest.json", raw)
            write_synced(stage / "manifest.sha256", (hashlib.sha256(raw).hexdigest() + "\n").encode("ascii"))
            verify_snapshot(stage, snapshot_id)
            sync_tree_directories(stage)
            # All CLI writers hold the directory lock. No partial ID is exposed.
            os.rename(stage, snapshot)
            sync_directory(repo)
        finally:
            if stage.exists():
                shutil.rmtree(stage)
    return {"id": snapshot_id}


def verify(repo, snapshot_id):
    with repository(repo):
        verify_snapshot(repo / snapshot_id, snapshot_id)
    return {"id": snapshot_id, "valid": True}


def restore(repo, snapshot_id, dest):
    if overlaps(repo, dest):
        reject("destination and repository overlap")
    with repository(repo):
        expected = verify_snapshot(repo / snapshot_id, snapshot_id)
        existed = dest.exists()
        original = dest.stat() if existed else None
        if existed and any(dest.iterdir()):
            reject("destination is not empty")
        dest.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        stage = Path(tempfile.mkdtemp(prefix=".backup-restore-", dir=dest.parent))
        try:
            copied = scan_tree(repo / snapshot_id / "tree", copy_to=stage)
            if copied != expected or scan_tree(stage) != expected:
                reject("restored data failed verification")
            sync_tree_directories(stage)
            # Recheck before publication, including directory identity.
            checked_path(dest)
            if existed:
                now = dest.stat()
                if (now.st_dev, now.st_ino) != (original.st_dev, original.st_ino) or any(dest.iterdir()):
                    reject("destination changed during restore")
            elif dest.exists():
                reject("destination appeared during restore")
            os.rename(stage, dest)
            sync_directory(dest.parent)
        finally:
            if stage.exists():
                shutil.rmtree(stage)
    return {"id": snapshot_id}


def list_snapshots(repo):
    snapshots = []
    with repository(repo, create=True):
        for path in sorted(repo.iterdir()):
            if not ID_RE.fullmatch(path.name):
                continue
            try:
                verify_snapshot(path, path.name)
            except (BackupError, OSError, ValueError, UnicodeError):
                # Neither interrupted nor corrupt snapshots are advertised.
                continue
            snapshots.append(path.name)
    return {"snapshots": snapshots}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("create", "verify", "restore", "list"):
        sub = commands.add_parser(name)
        sub.add_argument("--repo", required=True)
        if name != "list":
            sub.add_argument("--id", required=True)
        if name == "create":
            sub.add_argument("--source", required=True)
        if name == "restore":
            sub.add_argument("--dest", required=True)
    args = parser.parse_args()
    try:
        if args.command != "list":
            valid_id(args.id)
        repo = checked_path(args.repo)
        if args.command == "create":
            result = create(checked_path(args.source), repo, args.id)
        elif args.command == "verify":
            result = verify(repo, args.id)
        elif args.command == "restore":
            result = restore(repo, args.id, checked_path(args.dest))
        else:
            result = list_snapshots(repo)
    except (BackupError, OSError, ValueError, UnicodeError, RecursionError) as exc:
        print(json.dumps({"error": str(exc)}, ensure_ascii=True), file=sys.stderr)
        return 1
    print(json.dumps(result, ensure_ascii=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())
"""Local contract tests; all data is synthetic and confined to solution/evidence."""

import hashlib
import json
import os
from pathlib import Path
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import time
import unittest


ROOT = Path(__file__).resolve().parent
PROGRAM = ROOT / "backup.py"
EVIDENCE = ROOT / "evidence"
COMMANDS = EVIDENCE / "commands.jsonl"


def tree(path):
    result = {}
    for child in sorted(path.rglob("*")):
        relative = child.relative_to(path).as_posix()
        if child.is_symlink():
            result[relative] = ("symlink", os.readlink(child))
        elif child.is_dir():
            result[relative] = ("dir",)
        elif child.is_file():
            result[relative] = ("file", child.read_bytes())
        else:
            result[relative] = ("special", child.lstat().st_mode)
    return result


def record(argv, proc, seconds, timed_out=False):
    item = {"argv": argv, "exit_code": proc.returncode, "timeout_seconds": seconds,
            "timed_out": timed_out, "stdout": proc.stdout, "stderr": proc.stderr}
    with COMMANDS.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(item, ensure_ascii=True) + "\n")


class BackupTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix="test-", dir=EVIDENCE)
        self.addCleanup(self.tmp.cleanup)
        self.base = Path(self.tmp.name)
        self.source = self.base / "source"
        self.source.mkdir()
        self.repo = self.base / "repo"
        self.dest = self.base / "dest"
        (self.source / "empty dir").mkdir()
        (self.source / "nested").mkdir()
        (self.source / "nested" / "á 日本語.bin").write_bytes(bytes(range(256)) * 17)
        (self.source / "document.txt").write_bytes(b"original\x00\xff")
        (self.source / "zero").touch()

    def cli(self, operation, ok=True, **kwargs):
        kwargs.setdefault("repo", self.repo)
        argv = [sys.executable, str(PROGRAM), operation]
        for key, value in kwargs.items():
            argv += ["--" + key, str(value)]
        started = time.monotonic()
        try:
            proc = subprocess.run(argv, capture_output=True, text=True, timeout=30)
        except subprocess.TimeoutExpired as exc:
            record(argv, subprocess.CompletedProcess(argv, -1, str(exc.stdout or ""), str(exc.stderr or "")), 30, True)
            raise
        record(argv, proc, 30)
        elapsed = time.monotonic() - started
        if ok:
            self.assertEqual(proc.returncode, 0, proc.stderr)
            self.assertEqual(proc.stderr, "")
            result = json.loads(proc.stdout)
            self.assertIsInstance(result, dict)
            self.assertEqual(len(proc.stdout.splitlines()), 1)
            return result
        self.assertNotEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(proc.stdout, "")
        self.assertTrue(proc.stderr)
        return {"seconds": elapsed}

    def create(self, snapshot_id="v1"):
        before = tree(self.source)
        self.assertEqual(self.cli("create", source=self.source, id=snapshot_id), {"id": snapshot_id})
        self.assertEqual(before, tree(self.source))

    def test_v2_three_exact_versions_without_source(self):
        expected = {}
        expected["v1"] = tree(self.source)
        self.create("v1")
        (self.source / "document.txt").write_bytes(b"modified version two")
        (self.source / "added file").write_bytes(b"new\x00data")
        (self.source / "nested" / "á 日本語.bin").unlink()
        expected["v2"] = tree(self.source)
        self.create("v2")
        (self.source / "document.txt").unlink()
        (self.source / "added file").unlink()
        (self.source / "nested").rmdir()
        (self.source / "new empty").mkdir()
        (self.source / "third").write_bytes(b"third version")
        expected["v3"] = tree(self.source)
        self.create("v3")
        shutil.rmtree(self.source)
        self.assertEqual(self.cli("list"), {"snapshots": ["v1", "v2", "v3"]})
        for snapshot_id, contents in expected.items():
            with self.subTest(id=snapshot_id):
                self.assertEqual(self.cli("verify", id=snapshot_id), {"id": snapshot_id, "valid": True})
                dest = self.base / ("restore " + snapshot_id)
                self.assertEqual(self.cli("restore", id=snapshot_id, dest=dest), {"id": snapshot_id})
                self.assertEqual(tree(dest), contents)

    def test_empty_repo_and_sorted_ids(self):
        self.assertEqual(self.cli("list"), {"snapshots": []})
        for snapshot_id in ("z", "A", "b_2-", "1"):
            self.create(snapshot_id)
        self.assertEqual(self.cli("list"), {"snapshots": ["1", "A", "b_2-", "z"]})

    def test_empty_source_and_empty_preexisting_destination(self):
        shutil.rmtree(self.source)
        self.source.mkdir()
        self.create()
        self.dest.mkdir()
        self.cli("restore", id="v1", dest=self.dest)
        self.assertEqual(tree(self.dest), {})

    def test_id_limits(self):
        self.create("A" * 64)
        for value in ("", ".", "..", "../escape", "a/b", "a\\b", "_bad", "-bad", "é", "a.b", "a" * 65, "a\n"):
            with self.subTest(id=value):
                self.cli("create", source=self.source, id=value, ok=False)
                self.cli("verify", id=value, ok=False)
                self.cli("restore", id=value, dest=self.dest, ok=False)
        self.assertFalse(self.dest.exists())

    def test_missing_snapshot(self):
        self.cli("list")
        self.cli("verify", id="missing", ok=False)
        self.cli("restore", id="missing", dest=self.dest, ok=False)
        self.assertFalse(self.dest.exists())

    def test_missing_source(self):
        self.cli("create", source=self.base / "absent", id="v1", ok=False)
        self.assertEqual(self.cli("list"), {"snapshots": []})

    def test_id_not_overwritten(self):
        self.create()
        original = tree(self.repo)
        (self.source / "document.txt").write_bytes(b"later")
        self.cli("create", source=self.source, id="v1", ok=False)
        self.assertEqual(tree(self.repo), original)

    def test_protected_destination(self):
        self.create()
        self.dest.mkdir()
        (self.dest / "keep").write_bytes(b"protected\x00\xff")
        (self.dest / "empty").mkdir()
        original = tree(self.dest)
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        self.assertEqual(tree(self.dest), original)

    def test_destination_with_only_empty_directory_is_nonempty(self):
        self.create()
        self.dest.mkdir()
        (self.dest / "empty").mkdir()
        original = tree(self.dest)
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        self.assertEqual(tree(self.dest), original)

    def test_source_repo_overlap(self):
        original = tree(self.source)
        for repo in (self.source, self.source / "repo", self.base):
            with self.subTest(repo=str(repo)):
                self.cli("create", source=self.source, repo=repo, id="v1", ok=False)
                self.assertEqual(tree(self.source), original)

    def test_restore_repo_overlap(self):
        self.create()
        original = tree(self.repo)
        for dest in (self.repo, self.repo / "restored", self.base):
            self.cli("restore", id="v1", dest=dest, ok=False)
            self.assertEqual(tree(self.repo), original)

    def test_source_symlinks(self):
        for target in (self.source / "document.txt", self.source / "nested", self.base / "absent"):
            link = self.source / "link"
            link.symlink_to(target)
            before = tree(self.source)
            self.cli("create", source=self.source, id="v1", ok=False)
            self.assertEqual(tree(self.source), before)
            link.unlink()
        self.assertEqual(self.cli("list"), {"snapshots": []})

    def test_symlink_path_components_and_dotdot(self):
        self.create()
        link = self.base / "link"
        link.symlink_to(self.source, target_is_directory=True)
        for source in (link, link / "nested", link / ".." / "source"):
            self.cli("create", source=source, id="later", ok=False)
        repo_link = self.base / "repo-link"
        repo_link.symlink_to(self.repo, target_is_directory=True)
        for op in ("list", "verify", "restore", "create"):
            kwargs = {"repo": repo_link}
            if op != "list":
                kwargs["id"] = "v1"
            if op == "create":
                kwargs["source"] = self.source
            if op == "restore":
                kwargs["dest"] = self.dest
            self.cli(op, ok=False, **kwargs)
        self.dest.symlink_to(self.source, target_is_directory=True)
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        self.dest.unlink()
        parent = self.base / "dest-parent"
        parent.symlink_to(self.source, target_is_directory=True)
        self.cli("restore", id="v1", dest=parent / "new", ok=False)

    def test_symlink_in_snapshot_or_staging(self):
        self.create()
        original = tree(self.source)
        stage = self.repo / ".stage-junk"
        stage.mkdir()
        link = stage / "link"
        link.symlink_to(self.source)
        for op, kwargs in (("list", {}), ("verify", {"id": "v1"}), ("restore", {"id": "v1", "dest": self.dest})):
            self.cli(op, ok=False, **kwargs)
        link.unlink()
        stage.rmdir()
        snapshot = self.repo / "v1"
        shutil.rmtree(snapshot / "tree")
        (snapshot / "tree").symlink_to(self.source)
        self.cli("verify", id="v1", ok=False)
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        self.cli("list", ok=False)
        self.assertEqual(tree(self.source), original)

    def test_special_files(self):
        fifo = self.source / "fifo"
        os.mkfifo(fifo)
        self.cli("create", source=self.source, id="v1", ok=False)
        fifo.unlink()
        with socket.socket(socket.AF_UNIX) as sock:
            sock.bind(str(self.source / "socket"))
            self.cli("create", source=self.source, id="v1", ok=False)
        (self.source / "socket").unlink()
        self.create()
        os.mkfifo(self.repo / "v1" / "tree" / "fifo")
        self.cli("verify", id="v1", ok=False)
        self.cli("list", ok=False)
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        (self.repo / "v1" / "tree" / "fifo").unlink()
        self.dest.mkdir()
        os.mkfifo(self.dest / "fifo")
        self.cli("restore", id="v1", dest=self.dest, ok=False)
        self.assertTrue((self.dest / "fifo").exists())

    def test_regular_file_as_managed_directory(self):
        regular = self.base / "regular"
        regular.write_bytes(b"preserve")
        self.cli("create", source=regular, id="v1", ok=False)
        self.cli("list", repo=regular, ok=False)
        self.create()
        self.cli("restore", id="v1", dest=regular, ok=False)
        self.assertEqual(regular.read_bytes(), b"preserve")

    def test_corruption_of_each_regular_snapshot_file(self):
        self.create()
        paths = sorted(path for path in (self.repo / "v1").rglob("*") if path.is_file())
        for path in paths:
            original = path.read_bytes()
            for mode in ("alter", "truncate", "delete"):
                with self.subTest(file=str(path.relative_to(self.repo)), mode=mode):
                    if mode == "delete":
                        path.unlink()
                    elif mode == "truncate":
                        # An empty file must actually change to be a corruption.
                        path.write_bytes(b"" if original else b"damage")
                    else:
                        path.write_bytes(bytes([original[0] ^ 1]) + original[1:] if original else b"damage")
                    self.cli("verify", id="v1", ok=False)
                    self.cli("restore", id="v1", dest=self.dest, ok=False)
                    self.assertFalse(self.dest.exists())
                    self.assertEqual(self.cli("list"), {"snapshots": []})
                    self.dest.mkdir()
                    self.cli("restore", id="v1", dest=self.dest, ok=False)
                    self.assertEqual(tree(self.dest), {})
                    self.dest.rmdir()
                    path.write_bytes(original)
        self.cli("verify", id="v1")

    def test_directory_corruption_and_extra_files(self):
        self.create()
        empty = self.repo / "v1" / "tree" / "empty dir"
        empty.rmdir()
        self.cli("verify", id="v1", ok=False)
